/* ============================================================================
   META PIXEL — [DO UZUPEŁNIENIA]
   Pixel ładuje się WYŁĄCZNIE po zgodzie użytkownika w banerze cookies
   (patrz komponent CookieConsent niżej) — to wymóg RODO/ePrivacy, nie
   opcja stylistyczna. Sam skrypt bazowy Meta Pixel jest już wbudowany
   w funkcję loadMetaPixel() poniżej.

   Aby aktywować Pixel: wklej swój prawdziwy identyfikator z Menedżera
   zdarzeń Meta (Piksele → Szczegóły → Pixel ID) w miejsce
   "TWÓJ_PIXEL_ID" poniżej. Nic więcej nie trzeba zmieniać — banner
   zgody, zdarzenie PageView i zdarzenia niestandardowe
   (AIReadyQuizStart / AIReadyQuizComplete / AIReadyQuizProductClick)
   zaczną działać automatycznie, gdy użytkownik zaakceptuje cookies.
   ============================================================================ */
const META_PIXEL_ID = "TWÓJ_PIXEL_ID"; // [DO UZUPEŁNIENIA]

function loadMetaPixel(pixelId) {
  if (typeof window === "undefined" || window.fbq || !pixelId || pixelId === "TWÓJ_PIXEL_ID") return;
  /* eslint-disable */
  !function(f,b,e,v,n,t,s){if(f.fbq)return;n=f.fbq=function(){n.callMethod?
  n.callMethod.apply(n,arguments):n.queue.push(arguments)};if(!f._fbq)f._fbq=n;
  n.push=n;n.loaded=!0;n.version='2.0';n.queue=[];t=b.createElement(e);t.async=!0;
  t.src=v;s=b.getElementsByTagName(e)[0];s.parentNode.insertBefore(t,s)}(window,
  document,'script','https://connect.facebook.net/en_US/fbevents.js');
  /* eslint-enable */
  window.fbq('init', pixelId);
  window.fbq('track', 'PageView');
}

const COOKIE_CONSENT_KEY = "mb_cookie_consent";

function CookieConsent({ onNavigatePrivacy }) {
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const stored = typeof window !== "undefined" ? window.localStorage.getItem(COOKIE_CONSENT_KEY) : null;
    if (stored === "accepted") {
      loadMetaPixel(META_PIXEL_ID);
    } else if (stored !== "declined") {
      setVisible(true);
    }
  }, []);

  const accept = () => {
    window.localStorage.setItem(COOKIE_CONSENT_KEY, "accepted");
    setVisible(false);
    loadMetaPixel(META_PIXEL_ID);
  };
  const decline = () => {
    window.localStorage.setItem(COOKIE_CONSENT_KEY, "declined");
    setVisible(false);
  };

  if (!visible) return null;
  return (
    <div className="cookie-banner" role="dialog" aria-label="Zgoda na cookies">
      <p className="cookie-banner__text">
        Używam plików cookie do analizy ruchu i pomiaru skuteczności reklam (Meta Pixel).
        Możesz zaakceptować lub odrzucić — Twój wybór zapisuję lokalnie w przeglądarce.
        Więcej informacji znajdziesz w{" "}
        <button type="button" className="cookie-banner__link" onClick={onNavigatePrivacy}>
          Polityce Prywatności
        </button>.
      </p>
      <div className="cookie-banner__actions">
        <button type="button" className="btn btn--ghost" onClick={decline}>Odrzuć</button>
        <button type="button" className="btn btn--primary" onClick={accept}>Akceptuję</button>
      </div>
    </div>
  );
}

