/* ========================================================================= */

function useReveal() {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const io = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          io.unobserve(el);
        }
      },
      { threshold: 0.15 }
    );
    io.observe(el);
    return () => io.disconnect();
  }, []);
  return [ref, visible];
}

function Reveal({ children, delay = 0, className = "" }) {
  const [ref, visible] = useReveal();
  return (
    <div
      ref={ref}
      className={className}
      style={{
        opacity: visible ? 1 : 0,
        transform: visible ? "translateY(0)" : "translateY(18px)",
        transition: `opacity .7s cubic-bezier(.16,1,.3,1) ${delay}ms, transform .7s cubic-bezier(.16,1,.3,1) ${delay}ms`,
      }}
    >
      {children}
    </div>
  );
}

function Badge({ text, color = "magenta" }) {
  const c = COLOR_MAP[color] || COLOR_MAP.magenta;
  return (
    <span
      className="badge-pill"
      style={{ background: c.bg, color: c.fg }}
    >
      {text}
    </span>
  );
}

function scrollToId(id) {
  const el = document.getElementById(id);
  if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
}

/* Meta Pixel — bezpieczny wrapper. Nic nie robi, dopóki na stronie nie jest
   wgrany bazowy skrypt Meta Pixel (patrz komentarz [DO UZUPEŁNIENIA] na
   początku pliku). Gdy Pixel będzie aktywny, te zdarzenia zaczną działać
   automatycznie, bez dalszych zmian w tym pliku. */
function trackPixel(eventName, params) {
  if (typeof window !== "undefined" && typeof window.fbq === "function") {
    window.fbq("trackCustom", eventName, params || {});
  }
}

/* ---------- Nav ---------- */
function Nav({ onNavigateQuiz }) {
  const [open, setOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 8);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);
  const links = [
    { label: "O mnie", id: "about" },
    { label: "Podejście", id: "philosophy" },
    { label: "Darmowe", id: "free" },
    { label: "Produkty", id: "categories" },
    { label: "FAQ", id: "faq" },
    { label: "Czy jesteś AI Ready? TEST", type: "quiz" },
  ];
  const go = (l) => (l.type === "quiz" ? onNavigateQuiz() : scrollToId(l.id));
  return (
    <header className={`nav ${scrolled ? "nav--scrolled" : ""}`}>
      <div className="nav__inner">
        <nav className="nav__links">
          {links.map((l) => (
            <button key={l.label} onClick={() => go(l)}>
              {l.label}
            </button>
          ))}
        </nav>
        <button className="nav__cta" onClick={() => scrollToId("flagship")}>
          Zobacz produkty
        </button>
        <button className="nav__burger" onClick={() => setOpen((o) => !o)} aria-label="Menu">
          {open ? <X size={22} /> : <Menu size={22} />}
        </button>
      </div>
      {open && (
        <div className="nav__mobile">
          {links.map((l) => (
            <button
              key={l.label}
              onClick={() => {
                setOpen(false);
                go(l);
              }}
            >
              {l.label}
            </button>
          ))}
          <button
            className="nav__mobile-cta"
            onClick={() => {
              setOpen(false);
              scrollToId("flagship");
            }}
          >
            Zobacz produkty <ArrowRight size={16} />
          </button>
        </div>
      )}
    </header>
  );
}

/* ---------- Journey rail (signature element, desktop only) ---------- */
function JourneyRail() {
  const [active, setActive] = useState(0);
  useEffect(() => {
    const sections = JOURNEY.map((j) => document.getElementById(j.id)).filter(Boolean);
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) {
            const idx = JOURNEY.findIndex((j) => j.id === e.target.id);
            if (idx !== -1) setActive(idx);
          }
        });
      },
      { rootMargin: "-45% 0px -45% 0px", threshold: 0 }
    );
    sections.forEach((s) => io.observe(s));
    return () => io.disconnect();
  }, []);
  return (
    <div className="rail" aria-hidden="true">
      <div className="rail__line">
        <div className="rail__fill" style={{ height: `${(active / (JOURNEY.length - 1)) * 100}%` }} />
      </div>
      {JOURNEY.map((j, i) => (
        <button
          key={j.id}
          className={`rail__stop ${i === active ? "rail__stop--active" : ""} ${i < active ? "rail__stop--done" : ""}`}
          onClick={() => scrollToId(j.id)}
        >
          <span className="rail__num">{String(i + 1).padStart(2, "0")}</span>
          <span className="rail__label">{j.label}</span>
        </button>
      ))}
    </div>
  );
}

