/* ---------- Product card ---------- */
function ProductCard({ p, big = false }) {
  return (
    <div id={p.id} className={`product-card ${big ? "product-card--big" : ""}`}>
      <div className="product-card__media">
        <img
          src={p.image}
          alt={p.title}
          onError={(e) => {
            e.currentTarget.style.display = "none";
          }}
        />
        {p.badge && (
          <div className="product-card__badge-wrap">
            <Badge text={p.badge} color={p.badgeColor} />
            {p.badgeCaption && <span className="badge-caption">{p.badgeCaption}</span>}
          </div>
        )}
      </div>
      <div className="product-card__body">
        {p.subtitle && <div className="product-card__subtitle">{p.subtitle}</div>}
        <h3>{p.title}</h3>
        <p>{p.description}</p>
        <div className="product-card__footer">
          <div className="product-card__price">
            {p.price === 0 ? (
              <span className="price price--free">bezpłatnie</span>
            ) : (
              <>
                {p.oldPrice && <span className="price price--old">{p.oldPrice.toFixed(0)} zł</span>}
                <span className="price price--current">
                  {p.price.toFixed(2).replace(".", ",")} zł
                </span>
              </>
            )}
          </div>
          <a href={p.url} className={`btn ${p.price === 0 ? "btn--free" : "btn--card"}`}>
            {p.cta} <ArrowUpRight size={15} />
          </a>
        </div>
      </div>
    </div>
  );
}

