/* ---------- Legal pages ---------- */
/* ---------- Test gotowości ---------- */
function QuizGauge({ scores, maxByCategory }) {
  const cats = Object.keys(QUIZ_CATEGORIES).filter((c) => c !== "exp");
  return (
    <div className="qz-gauge">
      {cats.map((c) => {
        const pct = Math.min(100, Math.round((scores[c] / maxByCategory[c]) * 100)) || 0;
        return (
          <div className="qz-gauge__seg" key={c}>
            <div className="qz-gauge__track">
              <div className="qz-gauge__fill" style={{ height: `${pct}%`, background: QUIZ_CATEGORIES[c].color }} />
            </div>
            <span className="qz-gauge__label">{QUIZ_CATEGORIES[c].label}</span>
          </div>
        );
      })}
    </div>
  );
}

function QuizProgress({ step }) {
  const pct = Math.round((step / QUIZ_TOTAL) * 100);
  return (
    <div className="qz-progress">
      <div className="qz-progress__bar">
        <div className="qz-progress__fill" style={{ width: `${pct}%` }} />
      </div>
      <span className="qz-progress__count">{step} / {QUIZ_TOTAL}</span>
    </div>
  );
}

