function QuizResult({ scores, maxByCategory, forcedFlagship, onRestart, onSeeAll }) {
  const weakestCat = (() => {
    const cats = ["faq", "opinie", "ai", "listing"];
    let worst = cats[0];
    let worstRatio = Infinity;
    cats.forEach((c) => {
      const ratio = scores[c] / maxByCategory[c];
      if (ratio < worstRatio) {
        worstRatio = ratio;
        worst = c;
      }
    });
    return worst;
  })();

  const recommendedKey = forcedFlagship ? "exp" : weakestCat;
  const product = QUIZ_RESULT_PRODUCTS[recommendedKey];
  const totalPts = Object.values(scores).reduce((a, b) => a + b, 0);
  const totalMax = Object.values(maxByCategory).reduce((a, b) => a + b, 0);
  const overallPct = Math.round((totalPts / totalMax) * 100);
  const level = overallPct >= 75 ? "Zaawansowana" : overallPct >= 45 ? "W budowie" : "Początkująca";
  const whyText = {
    faq: "Bo dobre FAQ to nie tylko wygoda dla klienta. To też kontekst, który czytają wyszukiwarki i AI, zanim ktoś w ogóle do Ciebie napisze.",
    opinie: "Bo każda odpowiedź na opinię buduje albo osłabia zaufanie do Twojej marki, i to zanim klient zdąży zapytać.",
    ai: "Bo jeśli AI nie rozumie Twojej marki, nie poleci jej dalej, niezależnie od tego, jak dobry jest sam produkt.",
    listing: "Bo listing to pierwsze miejsce, w którym klient i algorytm decydują, czy zostać dłużej.",
  }[weakestCat];

  return (
    <div className="qz-card">
      <span className="eyebrow">Twój wynik</span>
      <h3 className="qz-result-level">Twoja marka jest na etapie: <span>{level}</span></h3>
      <QuizGauge scores={scores} maxByCategory={maxByCategory} />
      <p className="qz-diagnosis">
        {forcedFlagship ? (
          <>Chcesz kompletnego systemu, nie pojedynczej poprawki, to zawęża wybór.</>
        ) : (
          <>Największa luka jest tutaj: <strong>{QUIZ_CATEGORIES[weakestCat].label}</strong>. To miejsce, od którego warto zacząć.</>
        )}
      </p>
      {!forcedFlagship && <p className="qz-why">{whyText}</p>}
      <div className="qz-product">
        <div className="qz-product__media">
          <img src={product.image} alt={product.title} />
        </div>
        <div className="qz-product__body">
          <h4>{product.title}</h4>
          <p>{product.description}</p>
          <div className="qz-product__price">
            {product.oldPrice && <span className="qz-price-old">{product.oldPrice}</span>}
            <span className="qz-price-current">{product.price}</span>
          </div>
          <a
            href={product.url}
            className="btn btn--primary btn--wide"
            target="_blank"
            rel="noreferrer"
            onClick={() => trackPixel("AIReadyQuizProductClick", { result_category: recommendedKey })}
          >
            {product.cta} <ArrowRight size={17} />
          </a>
        </div>
      </div>
      <button className="qz-restart" onClick={onRestart}>
        <RotateCcw size={14} /> Zrób test jeszcze raz
      </button>
      <div className="qz-seeall">
        <p>Chcesz zobaczyć, co jeszcze możesz poprawić?</p>
        <button className="qz-seeall__btn" onClick={onSeeAll}>
          Zobacz wszystkie moje produkty <ArrowRight size={15} />
        </button>
      </div>
    </div>
  );
}

function QuizPage({ onBack, onSeeAll }) {
  useDocumentMeta("Czy Twoja marka jest AI Ready? Test — Michalina Bielawska", "/test-ai-ready");
  const [step, setStep] = useState(0);
  const [answers, setAnswers] = useState([]);
  const [forcedFlagship, setForcedFlagship] = useState(false);

  const maxByCategory = (() => {
    const max = { faq: 0, opinie: 0, ai: 0, listing: 0, exp: 0 };
    QUIZ_QUESTIONS.forEach((q) => {
      const best = Math.max(...q.options.map((o) => o.pts));
      max[q.cat] += best;
    });
    return max;
  })();

  const scores = (() => {
    const s = { faq: 0, opinie: 0, ai: 0, listing: 0, exp: 0 };
    answers.forEach((a, i) => {
      if (a) s[QUIZ_QUESTIONS[i].cat] += a.pts;
    });
    return s;
  })();

  const handleAnswer = (opt) => {
    setAnswers((prev) => {
      const next = [...prev];
      next[step - 1] = opt;
      return next;
    });
    if (opt.override === "exp") setForcedFlagship(true);
    const isLast = step === QUIZ_TOTAL;
    if (isLast) {
      const finalAnswers = [...answers];
      finalAnswers[step - 1] = opt;
      const finalScores = { faq: 0, opinie: 0, ai: 0, listing: 0, exp: 0 };
      finalAnswers.forEach((a, i) => {
        if (a) finalScores[QUIZ_QUESTIONS[i].cat] += a.pts;
      });
      const isFlagship = forcedFlagship || opt.override === "exp";
      let resultKey = "exp";
      if (!isFlagship) {
        const cats = ["faq", "opinie", "ai", "listing"];
        let worst = cats[0];
        let worstRatio = Infinity;
        cats.forEach((c) => {
          const ratio = finalScores[c] / maxByCategory[c];
          if (ratio < worstRatio) {
            worstRatio = ratio;
            worst = c;
          }
        });
        resultKey = worst;
      }
      trackPixel("AIReadyQuizComplete", { result_category: resultKey });
    }
    setStep((s) => (isLast ? QUIZ_TOTAL + 1 : s + 1));
  };

  const handleRestart = () => {
    setStep(0);
    setAnswers([]);
    setForcedFlagship(false);
  };

  return (
    <div className="legal qz-wrap">
      <div className="legal__inner">
        <button className="legal__back" onClick={onBack}>
          <ArrowLeft size={15} /> Wróć do strony głównej
        </button>
        {step === 0 && (
          <QuizIntro
            onStart={() => {
              trackPixel("AIReadyQuizStart");
              setStep(1);
            }}
          />
        )}
        {step >= 1 && step <= QUIZ_TOTAL && (
          <QuizQuestion
            q={QUIZ_QUESTIONS[step - 1]}
            step={step}
            onAnswer={handleAnswer}
            onBack={() => setStep((s) => Math.max(1, s - 1))}
          />
        )}
        {step === QUIZ_TOTAL + 1 && (
          <QuizResult
            scores={scores}
            maxByCategory={maxByCategory}
            forcedFlagship={forcedFlagship}
            onRestart={handleRestart}
            onSeeAll={onSeeAll}
          />
        )}
      </div>
    </div>
  );
}

/* Ustawia document.title i canonical <link> dla podstron — przywraca oryginalne
   wartości po odmontowaniu (powrót na stronę główną). */
function useDocumentMeta(title, path) {
  useEffect(() => {
    const prevTitle = document.title;
    const canonical = document.querySelector('link[rel="canonical"]');
    const prevHref = canonical ? canonical.getAttribute("href") : null;

    document.title = title;
    if (canonical) canonical.setAttribute("href", `https://michalinabielawska.pl${path}`);

    return () => {
      document.title = prevTitle;
      if (canonical && prevHref) canonical.setAttribute("href", prevHref);
    };
  }, [title, path]);
}

